import{_ as a,c as n,o as r,a3 as o}from"./chunks/framework.MI-M1z4O.js";const h=JSON.parse('{"title":"Release Notes and Changelog","description":"Major feature enhancements, security updates, and Architecture Decision Records (ADR) across versions of the Empasy SyncSeries platform","frontmatter":{"title":"Release Notes and Changelog","description":"Major feature enhancements, security updates, and Architecture Decision Records (ADR) across versions of the Empasy SyncSeries platform","sort":70,"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/en/ecosystem/changelog"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/ecosystem/changelog"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/ecosystem/changelog"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/ecosystem/changelog"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/ecosystem/changelog"}]]},"headers":[],"relativePath":"en/ecosystem/changelog.md","filePath":"en/ecosystem/changelog.md","lastUpdated":1795293539000}'),i={name:"en/ecosystem/changelog.md"};function t(l,e,s,c,d,m){return r(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="enterprise-release-notes-changelog" tabindex="-1">Enterprise Release Notes &amp; Changelog <a class="header-anchor" href="#enterprise-release-notes-changelog" aria-label="Permalink to “Enterprise Release Notes &amp; Changelog”">​</a></h1><p>This page transparently documents major updates, security patches, performance improvements, and Architecture Decision Records (ADR) across versions of SyncSeries.</p><hr><h2 id="v2-6-0-2026-09-24" tabindex="-1">[v2.6.0] - 2026-09-24 <a class="header-anchor" href="#v2-6-0-2026-09-24" aria-label="Permalink to “[v2.6.0] - 2026-09-24”">​</a></h2><h3 id="major-new-features-and-governance-overhaul" tabindex="-1">Major New Features and Governance Overhaul <a class="header-anchor" href="#major-new-features-and-governance-overhaul" aria-label="Permalink to “Major New Features and Governance Overhaul”">​</a></h3><ul><li><strong>Complete Overhaul of SyncVerse Task Approval (Governance) Control Tower</strong>: <ul><li>Established new top-level category <code>Task Approval</code> (<code>/governance</code>): complete with 5 dedicated views—Pending Approvals (HITL sign-off), Requirements Specification (Spec Studio), Code Review (Branch/PR), Schema Management (DB Governance), and Code Inspection (Quality Audit).</li><li>Streamlined 12 agent menus into 6 infrastructure-focused menus and standardized concise 2–5 character operational terminology.</li></ul></li><li><strong>Admin/MCP Server Role Separation and 0ms Async Startup Stabilization</strong>: <ul><li>Blocked unnecessary SyncVerse auto-registration on the Admin server (<code>self-registration.enabled: false</code>) to ensure UI startup independence.</li><li>Enforced asynchronous execution (<code>runAsync</code>) and a 3-second timeout on <code>AgentSelfRegistrationClient</code> dedicated to MCP servers, guaranteeing 0ms startup delay even when the central control tower is offline.</li></ul></li><li><strong>Enterprise-Wide Adoption of Zero-Mock and 4-Cycle Quality Verification Protocol</strong>: <ul><li>Completely eliminated Mock/Stub data across all core agents and shared modules (<code>verify-zero-mock.ps1</code> 100% passed).</li><li>Strictly prohibited Fake Normalcy state disguising and unified error handling under the RFC 7807 Problem Details standard.</li></ul></li><li><strong>SyncCMS Authoring Tool and Web Component Enhancements</strong>: <ul><li>Equipped the Tiptap shadow editor with multi-device (Desktop, Tablet, Mobile) responsive preview.</li><li>Added support for a real-time inline SEO analysis panel (<code>SeoAnalysisPanel.vue</code>) and command palette (<code>CommandPaletteModal.vue</code>).</li></ul></li></ul><hr><h2 id="v2-5-0-2026-06-15" tabindex="-1">[v2.5.0] - 2026-06-15 <a class="header-anchor" href="#v2-5-0-2026-06-15" aria-label="Permalink to “[v2.5.0] - 2026-06-15”">​</a></h2><h3 id="major-new-features" tabindex="-1">Major New Features <a class="header-anchor" href="#major-new-features" aria-label="Permalink to “Major New Features”">​</a></h3><ul><li><strong>Official Launch of SyncShop Autonomous eCommerce Operations Solution</strong>: <ul><li>Launched decoupled Headless eCommerce architecture (PMS, OMS, SMS, UMS) and mobile applications.</li><li>Real-time DB-integrated dynamic pricing and lossless snapshot rollback (<code>shop_batch_price_update</code>) engine.</li><li>Equipped with a 3-stage commerce agent swarm (Pricing Optimizer, Margin Safeguard, Executor).</li></ul></li><li><strong>Construction of Enterprise 8 Core Shared Business Modules (<code>sync-module-*</code>) and SyncSDK</strong>: <ul><li><code>sync-core</code>: Prevented Carrier Pinning in Java 25 Virtual Threads environments (<code>ReentrantLock</code>).</li><li><code>sync-module-ai</code>: Unified under <code>AgentScope Java</code> (<code>io.agentscope:agentscope-harness</code>) as the enterprise standard AI framework.</li><li><code>sync-module-deploy</code>: Integrated with Jenkins, GitHub Actions, and ArgoCD pipelines, plus K8s Pod monitoring.</li><li><code>sync-module-issue</code>: Universal issue tracker (GitHub, GitLab, Jira, Linear, Redmine) and portfolio Kanban board.</li><li><code>sync-module-rag</code>: Tri-Hybrid RAG knowledge search hub (Dense + Sparse + Reranker) and incident runbooks.</li><li>Integrated packaging for <code>sync-module-notification</code>, <code>sync-module-nl2sql</code>, and <code>sync-module-audit</code>.</li><li><code>SyncSDK</code>: Antigravity/OpenSwe SWE agent SDK integration with Mock-Free production guarantee.</li></ul></li></ul><hr><h2 id="v2-4-0-2026-03-01" tabindex="-1">[v2.4.0] - 2026-03-01 <a class="header-anchor" href="#v2-4-0-2026-03-01" aria-label="Permalink to “[v2.4.0] - 2026-03-01”">​</a></h2><h3 id="major-new-features-1" tabindex="-1">Major New Features <a class="header-anchor" href="#major-new-features-1" aria-label="Permalink to “Major New Features”">​</a></h3><ul><li><strong>SyncVerse Central Control Tower Enhancements</strong>: <ul><li>Equipped with an A2A (Agent-to-Agent) event routing engine powered by multi-agent collaboration MsgHub.</li><li>Added Server-Sent Events (SSE)-based real-time remote control streaming support.</li></ul></li><li><strong>Official Release of 3-Tier HITL (Human-in-the-Loop) Safety Governance Approval Pipeline</strong>: <ul><li>Implemented tier-based autonomous execution and administrator approval gateway for <code>LOW</code>, <code>MEDIUM</code>, and <code>HIGH</code> risk levels.</li></ul></li><li><strong>Enterprise-Wide Adoption of RFC 7807 Problem Details Standard Error Protocol</strong>: <ul><li>Proactively blocked Fake Normalcy state disguising and propagated structured diagnostic information.</li></ul></li></ul><h3 id="security-and-compliance" tabindex="-1">Security and Compliance <a class="header-anchor" href="#security-and-compliance" aria-label="Permalink to “Security and Compliance”">​</a></h3><ul><li>Completed mandatory corporate business disclosure information in the footer and introduced B2B Enterprise Terms of Service (<code>terms.html</code>).</li><li>Integrated Zero Data Retention (non-training guarantee) policy and security whitepaper.</li><li>Integrated 99.9% system uptime SLA indicator badge.</li></ul><hr><h2 id="v2-3-0-2026-02-15" tabindex="-1">[v2.3.0] - 2026-02-15 <a class="header-anchor" href="#v2-3-0-2026-02-15" aria-label="Permalink to “[v2.3.0] - 2026-02-15”">​</a></h2><h3 id="key-improvements" tabindex="-1">Key Improvements <a class="header-anchor" href="#key-improvements" aria-label="Permalink to “Key Improvements”">​</a></h3><ul><li><strong>SyncLLM FinOps Semantic Cache &amp; PII Masking Gateway</strong>: <ul><li>Redis-based zero-latency (12ms) semantic caching for identical queries with cosine similarity &gt;= 0.95.</li><li>Equipped with an inline real-time PII obfuscation filter capable of processing 2,500 RPS.</li></ul></li><li><strong>Intelligent High-Availability Automatic Failover (Circuit Breaker)</strong>: <ul><li>Seamless failover to a secondary backend within 50ms when 3 consecutive failures are detected from remote LLM providers (OpenAI, Anthropic, Bedrock).</li></ul></li></ul><hr><h2 id="v2-2-0-2026-01-20" tabindex="-1">[v2.2.0] - 2026-01-20 <a class="header-anchor" href="#v2-2-0-2026-01-20" aria-label="Permalink to “[v2.2.0] - 2026-01-20”">​</a></h2><h3 id="key-improvements-1" tabindex="-1">Key Improvements <a class="header-anchor" href="#key-improvements-1" aria-label="Permalink to “Key Improvements”">​</a></h3><ul><li><strong>SyncETA Vision-LLM 4.0 Selector Self-Healing Engine</strong>: <ul><li>Achieved a 98.4% self-healing success rate combining visual bounding boxes and text anchors upon DOM change detection.</li><li>Demonstrated an 81% reduction in global EdTech AIDT E2E regression testing time, from 4 hours down to 45 minutes.</li></ul></li><li><strong>Playwright Distributed Cluster Multi-Worker Node Integration</strong>: <ul><li>Orchestrates hundreds of browser containers concurrently in K8s environments for parallel test execution.</li></ul></li></ul><hr><h2 id="v2-1-0-2025-11-10" tabindex="-1">[v2.1.0] - 2025-11-10 <a class="header-anchor" href="#v2-1-0-2025-11-10" aria-label="Permalink to “[v2.1.0] - 2025-11-10”">​</a></h2><h3 id="key-improvements-2" tabindex="-1">Key Improvements <a class="header-anchor" href="#key-improvements-2" aria-label="Permalink to “Key Improvements”">​</a></h3><ul><li><strong>SyncBoot Spring Boot 4.0 / Java 25-Based MSA Framework</strong>: <ul><li>Orchestrated Saga pattern and automatic compensating transaction generation for distributed transaction consistency.</li><li>300% improvement in concurrent I/O throughput via Virtual Threads (Loom).</li><li>Integrated <code>AgentScope Java</code> (<code>io.agentscope:agentscope-harness</code>) as the enterprise standard AI framework.</li></ul></li></ul><hr><h2 id="v2-0-0-2025-09-01" tabindex="-1">[v2.0.0] - 2025-09-01 <a class="header-anchor" href="#v2-0-0-2025-09-01" aria-label="Permalink to “[v2.0.0] - 2025-09-01”">​</a></h2><h3 id="flagship-commercial-release" tabindex="-1">Flagship Commercial Release <a class="header-anchor" href="#flagship-commercial-release" aria-label="Permalink to “Flagship Commercial Release”">​</a></h3><ul><li><strong>Commercial Release of SyncSeries Enterprise 3-Layer Architecture</strong>: <ul><li>Layer 1: Governance and Autonomous Collaboration Layer (SyncVerse, SyncInsight)</li><li>Layer 2: Domain-Specific Autonomous Agent Layer (SyncETA, SyncBoot, SyncCMS, SyncCrawl, SyncLLM)</li><li>Layer 3: Platform Shared Infrastructure Layer (6-File SQL (<code>db/00_extensions.sql</code> ~ <code>05_sample_dev.sql</code>) structure, MCP JSON-RPC bus)</li></ul></li><li><strong>First shipment of Enterprise On-Premise (Air-Gapped) closed-network deployment pack</strong>.</li></ul>',32)])])}const p=a(i,[["render",t]]);export{h as __pageData,p as default};
